CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_status AS ENUM ('active','suspended','blocked');
CREATE TYPE user_role AS ENUM ('user','operator','admin','owner');
CREATE TYPE request_outcome AS ENUM ('queued','running','success','error','cancelled','blocked');

CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, status user_status NOT NULL DEFAULT 'active', role user_role NOT NULL DEFAULT 'user', group_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE api_keys (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, prefix text NOT NULL, digest text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL, expires_at timestamptz, revoked_at timestamptz);
CREATE INDEX api_keys_user_idx ON api_keys(user_id);
CREATE TABLE profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, codex_home text NOT NULL, backend_id text NOT NULL, status text NOT NULL DEFAULT 'active', config jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,name));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), profile_id uuid NOT NULL REFERENCES profiles(id), codex_thread_id text, title text NOT NULL, model text NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_updated_idx ON sessions(user_id,updated_at DESC);
CREATE TABLE usage_cycles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, kind text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz, window_seconds integer, status text NOT NULL DEFAULT 'active', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE budget_limits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cycle_id uuid NOT NULL REFERENCES usage_cycles(id), subject_type text NOT NULL, subject_id uuid, model text, metric text NOT NULL, limit_value bigint NOT NULL CHECK(limit_value>0), mode text NOT NULL CHECK(mode IN ('hard','soft')), warning_percent integer NOT NULL DEFAULT 80 CHECK(warning_percent BETWEEN 1 AND 100), tolerance_basis_points integer NOT NULL DEFAULT 0, enabled boolean NOT NULL DEFAULT true);
CREATE INDEX budget_subject_idx ON budget_limits(subject_type,subject_id,cycle_id);
CREATE TABLE requests (id uuid PRIMARY KEY, idempotency_key text NOT NULL UNIQUE, user_id uuid NOT NULL REFERENCES users(id), session_id uuid REFERENCES sessions(id), profile_id uuid NOT NULL REFERENCES profiles(id), device_id text, backend_id text NOT NULL, model text NOT NULL, status request_outcome NOT NULL, started_at timestamptz NOT NULL, finished_at timestamptz, duration_ms bigint, input_tokens bigint NOT NULL DEFAULT 0, output_tokens bigint NOT NULL DEFAULT 0, cached_input_tokens bigint NOT NULL DEFAULT 0, reasoning_tokens bigint NOT NULL DEFAULT 0, calls integer NOT NULL DEFAULT 1, compactions integer NOT NULL DEFAULT 0, tools jsonb NOT NULL DEFAULT '[]', tasks jsonb NOT NULL DEFAULT '[]', error_code text, estimated_cost_micros bigint NOT NULL DEFAULT 0, weighted_units bigint NOT NULL DEFAULT 0, measurement_source text NOT NULL, confidence text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}');
CREATE INDEX requests_user_started_idx ON requests(user_id,started_at DESC);
CREATE INDEX requests_model_started_idx ON requests(model,started_at DESC);
CREATE TABLE quota_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES requests(id) ON DELETE CASCADE, budget_limit_id uuid NOT NULL REFERENCES budget_limits(id), reserved bigint NOT NULL, actual bigint, status text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX reservations_limit_status_idx ON quota_reservations(budget_limit_id,status);
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid, event text NOT NULL, target_type text NOT NULL, target_id text, request_id uuid, ip_hash text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_created_idx ON audit_events(created_at DESC);
CREATE INDEX audit_actor_idx ON audit_events(actor_user_id);
